package sprint

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func gauntletFixture(t *testing.T) (string, Sprint) {
	t.Helper()
	root := t.TempDir()
	projectRoot := filepath.Join(root, "projects", "alpha")
	sprintRoot := filepath.Join(projectRoot, "sprints", "31-web")
	if err := os.MkdirAll(sprintRoot, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(projectRoot, "project-index.md"), []byte("# Project Index: alpha\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(sprintRoot, "sprint-index.md"), []byte("# Sprint Index: web\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	return root, Sprint{Project: "alpha", Slug: "31-web", Path: sprintRoot}
}

// Proves a crash between O_EXCL create and lock-info write permanently wedges
// the mutation lease, and that ReconcileInterruptedMutation silently skips the
// sprint in that state.
func TestZZGauntletCorruptLockWedgesLease(t *testing.T) {
	for name, content := range map[string][]byte{
		"empty":   {},
		"partial": []byte(`{"project":"alpha","pid":`),
	} {
		t.Run(name, func(t *testing.T) {
			root, sp := gauntletFixture(t)
			lockPath := filepath.Join(root, ".ultraplan", "locks", "sprint", sp.Project+"--"+sp.Slug+".lock")
			if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(lockPath, content, 0o644); err != nil {
				t.Fatal(err)
			}
			svc := NewService(root)
			if _, _, err := svc.acquireMutationContext(context.Background(), sp.Project, sp.Slug); !errors.Is(err, ErrVerificationConflict) {
				t.Fatalf("acquire err=%v, want ErrVerificationConflict", err)
			} else if !strings.Contains(err.Error(), "unreadable") {
				t.Fatalf("acquire err=%v, want unreadable-lock classification", err)
			}

			// Seed an expired running review attempt (dead PID, stale heartbeat).
			now := time.Date(2026, 8, 20, 12, 0, 0, 0, time.UTC)
			stages := emptyPlanningStageStates(sp)
			state := NewFlowState(sp, stages, now.Add(-4*time.Hour))
			state.Review = &ReviewStageState{
				Path:   ArtifactRelPath(sp, StageReview),
				Status: ReviewRunning,
				ActiveAttempt: &VerificationAttempt{
					ID: "review-1", Status: AttemptRunning,
					StartedAt: now.Add(-4 * time.Hour), HeartbeatAt: now.Add(-4 * time.Hour),
					OwnerPID: 99999999,
				},
			}
			if err := SaveFlowState(root, sp, state); err != nil {
				t.Fatalf("seed flow state: %v", err)
			}

			changed, err := NewService(root).ReconcileInterruptedMutation(context.Background(), sp.Project, sp.Slug)
			if err != nil || changed {
				t.Fatalf("reconcile changed=%t err=%v; want silent conflict skip (false,nil)", changed, err)
			}
			reloaded, err := LoadFlowState(root, sp)
			if err != nil {
				t.Fatal(err)
			}
			if reloaded.Review == nil || reloaded.Review.ActiveAttempt == nil {
				t.Fatal("expired attempt was reconciled despite wedged lease")
			}
			if !attemptExpired(reloaded.Review.ActiveAttempt, now) {
				t.Fatal("seeded attempt should be expired by rule")
			}

			// Wedge persists across attempts.
			svc2 := NewService(root)
			svc2.now = func() time.Time { return now }
			if _, _, err := svc2.acquireMutationContext(context.Background(), sp.Project, sp.Slug); err == nil {
				t.Fatal("wedge unexpectedly cleared")
			}
		})
	}
}

// Re-enacts the Status refresh save interleaved after a review completion to
// show the completed review evidence is silently lost (no CAS/ownership check).
func TestZZGauntletStatusRefreshStompsCompletedReview(t *testing.T) {
	root, sp := gauntletFixture(t)
	now := time.Date(2026, 8, 20, 12, 0, 0, 0, time.UTC)

	// Prior state visible when Status begins its load->save window.
	stages := emptyPlanningStageStates(sp)
	prior := NewFlowState(sp, stages, now.Add(-time.Hour))
	prior.Review = &ReviewStageState{Path: ArtifactRelPath(sp, StageReview), Status: ReviewRunning, Fingerprint: "old-fp"}
	if err := SaveFlowState(root, sp, prior); err != nil {
		t.Fatal(err)
	}

	// Status: LoadFlowState snapshot.
	statusView, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatal(err)
	}

	// Concurrent reality: review completes and persists its record first.
	completed := NewFlowState(sp, stages, now)
	completed.Review = &ReviewStageState{
		Path: ArtifactRelPath(sp, StageReview), Status: ReviewCompleted,
		Fingerprint: "new-fp", ArtifactDigest: "deadbeef", Stale: false,
		LastComplete: &ReviewCompletion{Verdict: ReviewPass, Artifact: ArtifactRelPath(sp, StageReview), ArtifactDigest: "deadbeef", InputFingerprint: "new-fp", CompletedAt: now},
	}
	completed.Smoke = nil
	completed.QA = nil
	if err := SaveFlowState(root, sp, completed); err != nil {
		t.Fatal(err)
	}

	// Status finishes: builds refreshed from its stale snapshot and saves.
	refreshed := NewFlowState(sp, DeriveStages(sp, ArtifactSnapshot{}, statusView.Stages), now)
	refreshed.Review = statusView.Review
	if err := SaveFlowState(root, sp, refreshed); err != nil {
		t.Fatalf("status refresh save: %v", err)
	}

	final, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	if final.Review == nil || final.Review.Status != ReviewCompleted {
		t.Fatalf("completed review evidence lost: %+v", final.Review)
	}
}
EOF
